package africa.growtogether.platform.eip.payment;
import africa.growtogether.platform.common.persistence.AuditedTenantEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="eip_payment_settlements",indexes={@Index(name="ux_eip_settlement_provider_ref",columnList="tenant_id,connector_code,provider_settlement_reference",unique=true),@Index(name="ix_eip_settlement_date",columnList="tenant_id,settlement_date,settlement_status")})
public class PaymentSettlement extends AuditedTenantEntity {
 @Column(name="connector_code",nullable=false,length=100) private String connectorCode; @Column(name="provider_settlement_reference",nullable=false,length=180) private String providerSettlementReference; @Column(name="settlement_date",nullable=false) private LocalDate settlementDate; @Column(name="gross_amount",nullable=false,precision=19,scale=4) private BigDecimal grossAmount; @Column(name="fee_amount",nullable=false,precision=19,scale=4) private BigDecimal feeAmount; @Column(name="net_amount",nullable=false,precision=19,scale=4) private BigDecimal netAmount; @Column(name="currency",nullable=false,length=3) private String currency; @Enumerated(EnumType.STRING) @Column(name="settlement_status",nullable=false,length=30) private SettlementStatus status=SettlementStatus.RECEIVED;
 protected PaymentSettlement(){} public PaymentSettlement(UUID tenantId,String connector,String ref,LocalDate date,BigDecimal gross,BigDecimal fee,String currency){setTenantId(tenantId);connectorCode=connector;providerSettlementReference=ref;settlementDate=date;grossAmount=gross;feeAmount=fee==null?BigDecimal.ZERO:fee;netAmount=grossAmount.subtract(feeAmount);this.currency=currency.toUpperCase();} public UUID id(){return getId();} public SettlementStatus status(){return status;} public void matched(){status=SettlementStatus.MATCHED;} public BigDecimal netAmount(){return netAmount;}
}
